/* ---- category index + helpers ---- */
MH.VOCAB_KEYS = Object.keys(MH.VOCAB);
MH.vocabByCat = function (cat) {
  return MH.VOCAB_KEYS.filter(function (k) { return MH.VOCAB[k].c === cat; }).map(function (k) { return MH.VOCAB[k]; });
};
MH.vocab = function (key) { return MH.VOCAB[key]; };